-- Daily challenges for 2026-11-27: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-27. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.
-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('enjoying-puzzles-and-brain-games', 'Enjoying Puzzles and Brain Games', 'For anyone who wants a calm, absorbing break that gives a busy mind something gentle to do. Each day is one small puzzle, riddle or word game to try alone or with others, for the simple pleasure of figuring things out.', 'Play', 365, array['Mindfulness', 'Self-Care']::text[], 1, '2026-11-27T17:00:00+00:00'::timestamptz),
  ('soaking-up-daylight', 'Soaking Up Daylight', 'For anyone who spends most of the day indoors or feels dimmer on gray days. Each day is one small way to get more natural light into your mornings, work hours and home, safely and in every season.', 'Wellbeing', 365, array['Self-Care', 'Sleep', 'Mindfulness']::text[], 1, '2026-11-27T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('enjoying-puzzles-and-brain-games', 'soaking-up-daylight');

